--- a/tests/add_channel_checks.cc
+++ b/tests/add_channel_checks.cc
@@ -29,8 +29,9 @@

 // Regression tests for the Cb/Cr size check in HeifPixelImage::add_channel().
 //
-// A Cb/Cr plane must have exactly the chroma-subsampled size of the logical image
-// (round_up). Building one at a different size makes the plane's allocation disagree
+// A Cb/Cr plane must have the chroma-subsampled size of the logical image
+// (round_up), plus at most one even-alignment sample when the luma width is odd.
+// Building one at a different size makes the plane's allocation disagree
 // with the size other code derives from the logical dimensions. An oversized plane
 // let extend_to_size_with_zero() underflow its per-row fill length and write ~4 GB
 // past the plane (GHSA-j2rv-58fh-w8pw); an undersized plane caused out-of-bounds
@@ -82,6 +83,15 @@ TEST_CASE("add_channel accepts correctly-subsampled chroma planes") {
     REQUIRE(image->add_channel(heif_channel_Cr, 7, 5, 8, limits).error_code == heif_error_Ok);
   }

+  SECTION("4:2:0, odd width keeps one alignment sample") {
+    auto image = std::make_shared<HeifPixelImage>();
+    image->create(13, 8, heif_colorspace_YCbCr, heif_chroma_420);
+    REQUIRE(image->add_channel(heif_channel_Y, 13, 8, 8, limits).error_code == heif_error_Ok);
+    // round_up is 7x4; the even coded width is one sample wider.
+    REQUIRE(image->add_channel(heif_channel_Cb, 8, 4, 8, limits).error_code == heif_error_Ok);
+    REQUIRE(image->add_channel(heif_channel_Cr, 8, 4, 8, limits).error_code == heif_error_Ok);
+  }
+
   SECTION("4:2:2 subsamples width only") {
     auto image = std::make_shared<HeifPixelImage>();
     image->create(12, 8, heif_colorspace_YCbCr, heif_chroma_422);

diff --git a/libheif/image/pixelimage.cc b/libheif/image/pixelimage.cc
index 81a0583..53fa219 100644
--- a/libheif/image/pixelimage.cc
+++ b/libheif/image/pixelimage.cc
@@ -721,7 +721,18 @@ Error HeifPixelImage::extend_to_size_with_zero(uint32_t width, uint32_t height,
     get_subsampled_size(width, height, component.m_channel, m_chroma,
                         &subsampled_width, &subsampled_height);

-    if (subsampled_width < component.m_width || subsampled_height < component.m_height) {
+    // Cb/Cr are stored at the chroma-subsampled size of the logical image, which
+    // add_channel() enforces, so the size derived from the logical image is the
+    // plane's size. Use that here, as every other consumer does, instead of the
+    // width recorded on the plane.
+    uint32_t plane_width = component.m_width;
+    uint32_t plane_height = component.m_height;
+    if (component.m_channel == heif_channel_Cb || component.m_channel == heif_channel_Cr) {
+      get_subsampled_size(m_width, m_height, component.m_channel, m_chroma,
+                          &plane_width, &plane_height);
+    }
+
+    if (subsampled_width < plane_width || subsampled_height < plane_height) {
       return Error{heif_error_Usage_error,
                    heif_suberror_Invalid_parameter_value,
                    "Cannot extend an image to a size smaller than an existing plane."};
